(x, y, t) => {
  let nx = x / 480, ny = y / 240;
  let a = 0, b = 0;
  for (let i = 0; i < 8; i++) {
    let p = t * 0.18 + i * 0.785;
    let sx = 0.5 + 0.4 * Math.sin(p + i * 0.3);
    let sy = 0.5 + 0.3 * Math.cos(p * 0.7 + i * 1.1);
    let dx = nx - sx, dy = ny - sy;
    let d = Math.sqrt(dx * dx + dy * dy);
    let w = Math.exp(-d * 2.2);
    a += Math.sin(d * (20 + i * 3) - t * (0.6 + i * 0.1)) * w;
    b += Math.cos(d * (15 + i * 2.5) + t * (0.4 + i * 0.08)) * w;
  }
  let a2 = a * a, b2 = b * b, ab = a * b;
  let react = a2 - b2 * 0.6 + ab * 0.4 - 0.08;
  let spots = Math.tanh(react * 10);
  let stripes = Math.sin(react * 28) * 0.2;
  let micro = Math.sin(a * 40 + b * 35 + t * 2) * 0.08;
  let p = Math.max(0, Math.min(1, spots * 0.65 + stripes + micro + 0.52));
  p = p * p * (3 - 2 * p);
  let h = t * 0.02 + p * 0.18 + Math.sin(nx * 2 + ny * 2 + t * 0.1) * 0.05;
  let r = 0.5 + 0.48 * Math.cos(6.2832 * (h + 0.0) + 0.4);
  let g = 0.5 + 0.48 * Math.cos(6.2832 * (h + 0.32) + 0.2);
  let bl = 0.5 + 0.48 * Math.cos(6.2832 * (h + 0.64) + 0.6);
  let shadow = Math.max(0, Math.min(1, react * 5 + 0.5));
  let lum = 0.18 + 0.82 * p - shadow * 0.1;
  let glow = Math.exp(-Math.abs(react) * 6) * 0.15;
  return [
    Math.min(1, r * lum + glow * 0.8),
    Math.min(1, g * lum + glow * 0.5),
    Math.min(1, bl * lum + glow * 0.9)
  ];
}
